import { serve } from 'https://deno.land/std@0.168.0/http/server.ts';
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

const json = (data, status = 200) =>
  new Response(JSON.stringify(data), { status, headers: { ...CORS, 'Content-Type': 'application/json' } });

serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS });
  try {
    const { action, id, password } = await req.json();
    const adminPassword = Deno.env.get('ADMIN_PASSWORD');
    if (!adminPassword || password !== adminPassword) return json({ error: 'Unauthorized' }, 401);
    const supabase = createClient(Deno.env.get('SUPABASE_URL'), Deno.env.get('SUPABASE_SERVICE_ROLE_KEY'));
    if (action === 'list') {
      const { data, error } = await supabase.from('ud_review').select('*').order('created_at', { ascending: false });
      if (error) throw error;
      return json(data);
    }
    if (action === 'approve' || action === 'reject') {
      const { error } = await supabase.from('ud_review').update({ approved: action === 'approve' }).eq('id', id);
      if (error) throw error;
      return json({ ok: true });
    }
    if (action === 'delete') {
      const { error } = await supabase.from('ud_review').delete().eq('id', id);
      if (error) throw error;
      return json({ ok: true });
    }
    return json({ error: 'Unknown action' }, 400);
  } catch (e) {
    return json({ error: String(e) }, 500);
  }
});
